<?php
require '/wordpress/wp-load.php';wp_set_current_user(1);
function inline_test($ok,$message){if(!$ok)throw new Exception($message);}
$pdf=get_posts(['post_type'=>'attachment','post_mime_type'=>'application/pdf','numberposts'=>1])[0]->ID;$mp3=get_posts(['post_type'=>'attachment','post_mime_type'=>'audio/mpeg','numberposts'=>1])[0]->ID;$image=get_posts(['post_type'=>'attachment','post_mime_type'=>'image/jpeg','numberposts'=>1])[0]->ID;
$id=wp_insert_post(['post_type'=>'qrp_item','post_status'=>'publish','post_title'=>'Znaczniki materiałów','post_content'=>'<p>Początek.</p><p>[qrp_image id="'.$image.'"]</p><p>[qrp_file id="'.$pdf.'"]</p><p>Środek.</p><p>[qrp_file id="'.$mp3.'"]</p><p>Koniec.</p>']);update_post_meta($id,'qrp_gallery',[$image]);update_post_meta($id,'qrp_attachments',[$pdf,$mp3]);update_post_meta($id,'qrp_primary_file',$pdf);update_post_meta($id,'qrp_delivery','preview');update_post_meta($id,'qrp_file_labels',[$pdf=>'Przewodnik PDF',$mp3=>'Opowieść audio']);
inline_test(qrp_delivery(get_post($id))==='content','Inline markers force content presentation');inline_test(qrp_inline_ids(get_post($id))===[$image,$pdf,$mp3],'Valid inline media detected');global $post;$post=get_post($id);setup_postdata($post);$html=qrp_template('entry',['s'=>qrp_settings()]);inline_test(substr_count($html,'data-pdf-viewer')===1,'Inline PDF appears only once');inline_test(substr_count($html,'<audio ')===1,'Inline MP3 appears only once');inline_test(str_contains($html,'qrp-inline-image'),'Image marker displays photo');inline_test(!str_contains($html,'[qrp_file'),'Published page hides markers');inline_test(str_contains($html,'PDF: Przewodnik PDF')&&str_contains($html,'MP3: Opowieść audio'),'Inline media uses entry display labels');inline_test(strpos($html,'Początek.')<strpos($html,'data-pdf-viewer')&&strpos($html,'data-pdf-viewer')<strpos($html,'Środek.'),'Inline file maintains text order');$escaped=clone $post;$escaped->post_content='[[qrp_file id="'.$pdf.'"]]';inline_test(!qrp_inline_ids($escaped),'Escaped markers do not suppress attachments');$unrelated=wp_insert_attachment(['post_mime_type'=>'audio/mpeg','post_title'=>'Niepowiązany plik','post_status'=>'inherit']);inline_test(str_contains(do_shortcode('[qrp_file id="'.$unrelated.'"]'),'Materiał niedostępny'),'Unassigned files cannot be exposed by arbitrary markers');
$s=qrp_sanitize_settings(['favicon'=>$image,'gsc_method'=>'dns','seo_verification'=>'google-site-verification=abc_123-XYZ']);inline_test($s['seo_verification']==='abc_123-XYZ','DNS TXT prefix normalized');$s['seo_verification']='abc_123-XYZ';update_option('qrp_settings',$s);global $wp_query;$wp_query=new WP_Query(['post_type'=>'qrp_item','p'=>$id]);ob_start();do_action('wp_head');$head=ob_get_clean();inline_test(str_contains($head,'rel="icon"'),'Custom favicon emitted');inline_test(!str_contains($head,'name="google-site-verification"'),'DNS mode does not impersonate HTML verification');$s=qrp_sanitize_settings(['gsc_method'=>'html','seo_verification'=>'<meta name="google-site-verification" content="abc_123-XYZ" />']);inline_test($s['seo_verification']==='abc_123-XYZ','HTML meta token parsed');update_option('qrp_settings',$s);ob_start();do_action('wp_head');$head=ob_get_clean();inline_test(str_contains($head,'name="google-site-verification" content="abc_123-XYZ"'),'HTML mode renders verification tag');echo 'INLINE MEDIA AND FAVICON TESTS PASSED';
